/**
 * Sent → delivered → opened → watched → replied across every recipient-directed whisp (whisper_link, group_whisper, ghost_boost) — circle_drop is excluded since it has no single recipient to fall off for.
 */
export type AdminFunnelStatsFunnel = {
  sent: number;
  delivered: number;
  failed: number;
  opened: number;
  watched: number;
  replied: number;
  /** Recipients who answered "yes" to "was this something you needed to hear?" */
  appreciated: number;
};

export type AdminFunnelStatsGhostBoost = {
  campaigns: number;
  totalMatched: number;
  avgMatchedPerCampaign: number;
};

export type AdminFunnelStatsCircles = {
  totalCircles: number;
  totalMembers: number;
  totalDrops: number;
};

/**
 * Usage of the "Not sure what to send?" AI concierge (POST /whisps/concierge).
 */
export type AdminFunnelStatsConcierge = {
  totalRequests: number;
  /** Requests where at least one Suggestions Library video was matched (as opposed to falling back to note-draft-only). */
  requestsWithVideoMatch: number;
  /** Whisps actually sent using a concierge request's video and/or note (whisps.conciergeRequestId is set). */
  sends: number;
};

/**
 * Proof the Twilio-skip matching in lib/deliver.ts is saving money — every whisper_link/group_whisper SMS-or-WhatsApp send attempt (initial send, reminders, reveal-request, reply-to-recipient), split by whether it was routed in-app (recipient phone matched a known, OTP-verified user) or actually went through Twilio (unmatched).
 */
export type AdminFunnelStatsPhoneMatchRouting = {
  inApp: number;
  twilio: number;
  /** Percentage (0-100) of these sends that were routed in-app instead of through Twilio. */
  matchRate: number;
};

/**
 * Anonymous invite-a-friend (routes/invites.ts) volume and how many actually converted into a real account.
 */
export type AdminFunnelStatsInvites = {
  sent: number;
  /** Invites whose recipient actually created a Blind Whisper account via the invite link (status = 'joined'). */
  joined: number;
  /** Percentage (0-100) of sent invites that converted to a joined account. */
  conversionRate: number;
};

/**
 * Text Whisp (routes/textWhisps.ts) volume and how far it gets read/replied — a separate, text-only content type, not folded into the whisp funnel above. deliveredInApp/deliveredGuest mirror phoneMatchRouting's in-app-vs-Twilio split, one level up (recipientUserId set vs. null at send time).
 */
export type AdminFunnelStatsTextWhisps = {
  sent: number;
  read: number;
  replied: number;
  /** Text Whisps whose recipient phone matched a known, verified account at send time (recipientUserId is set) — delivered entirely in-app. */
  deliveredInApp: number;
  /** Text Whisps sent to a phone number that wasn't a known, verified account at send time (recipientUserId is null) — delivered as a public guest link over SMS. */
  deliveredGuest: number;
};

export interface AdminChannelDeliveryStat {
  channel: string;
  attempts: number;
  succeeded: number;
  failed: number;
  successRate: number;
}

export interface AdminFunnelStats {
  /** Sent → delivered → opened → watched → replied across every recipient-directed whisp (whisper_link, group_whisper, ghost_boost) — circle_drop is excluded since it has no single recipient to fall off for. */
  funnel: AdminFunnelStatsFunnel;
  deliveryByChannel: AdminChannelDeliveryStat[];
  ghostBoost: AdminFunnelStatsGhostBoost;
  circles: AdminFunnelStatsCircles;
  /** Usage of the "Not sure what to send?" AI concierge (POST /whisps/concierge). */
  concierge: AdminFunnelStatsConcierge;
  /** Proof the Twilio-skip matching in lib/deliver.ts is saving money — every whisper_link/group_whisper SMS-or-WhatsApp send attempt (initial send, reminders, reveal-request, reply-to-recipient), split by whether it was routed in-app (recipient phone matched a known, OTP-verified user) or actually went through Twilio (unmatched). */
  phoneMatchRouting: AdminFunnelStatsPhoneMatchRouting;
  /** Anonymous invite-a-friend (routes/invites.ts) volume and how many actually converted into a real account. */
  invites: AdminFunnelStatsInvites;
  /** Text Whisp (routes/textWhisps.ts) volume and how far it gets read/replied — a separate, text-only content type, not folded into the whisp funnel above. deliveredInApp/deliveredGuest mirror phoneMatchRouting's in-app-vs-Twilio split, one level up (recipientUserId set vs. null at send time). */
  textWhisps: AdminFunnelStatsTextWhisps;
}

